fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since arr.len() > 0 is guaranteed, we just need to check adjacent elements.
    for i in 1..arr.len() {
        if arr[i - 1] > arr[i] {
            return false;
        }
    }
    true
}

